pragma solidity ^0.8.0;

abstract contract Extsload {
    function extsload(bytes32[] memory slots)
        external
        view
        returns (bytes32[] memory)
    {
        for (uint256 i; i < slots.length; i++) {
            bytes32 slot = slots[i];
            bytes32 val;
            assembly {
                val := sload(slot)
            }
            slots[i] = val;
        }
        return slots;
    }
}

