import {IInterestRateModel} from "./interfaces/IInterestRateModel.sol";
import {WadRayMath} from "./libraries/WadRayMath.sol";

/**
 * @title InterestRateModel
 * @notice Implements a utilization-based interest rate curve with a kink point.
 * @dev The model uses two slopes:
 *      - Below the kink: a gentle slope to incentivize borrowing.
 *      - Above the kink: a steep slope to discourage over-utilization.
 *
 *      Rate Formula:
 *        if utilization <= kink:
 *          borrowRate = baseRate + (utilization * slope1)
 *        else:
 *          borrowRate = baseRate + (kink * slope1) + ((utilization - kink) * slope2)
 *
 * AUDIT FOCUS AREAS:
 * [A-1] Precision loss in rate calculations at boundary conditions
 * [A-2] Rate manipulation via dust deposits/withdrawals
 * [A-3] Utilization ratio edge cases (0 deposits, 0 borrows)
 */
contract InterestRateModel is IInterestRateModel {
    using WadRayMath for uint256;

    // ══════════════════════════════════════════════════════════════════
    //                          CONSTANTS
    // ══════════════════════════════════════════════════════════════════

    /// @notice Base annual borrow rate (2%)
    uint256 public constant BASE_RATE = 0.02e18;

    /// @notice Slope before kink utilization (4%)
    uint256 public constant SLOPE_1 = 0.04e18;

    /// @notice Slope after kink utilization (75%) — steep to discourage over-borrowing
    uint256 public constant SLOPE_2 = 3.00e18;

    /// @notice Optimal utilization rate / kink point (80%)
    uint256 public constant KINK = 0.80e18;

    /// @notice Reserve factor — percentage of interest that goes to protocol reserves (10%)
    uint256 public constant RESERVE_FACTOR = 0.10e18;

    /// @notice Seconds per year for rate conversion
    uint256 public constant SECONDS_PER_YEAR = 365.25 days;

    // ══════════════════════════════════════════════════════════════════
    //                       RATE CALCULATIONS
    // ══════════════════════════════════════════════════════════════════

    /**
     * @inheritdoc IInterestRateModel
     * @dev Returns annualized borrow rate based on current utilization.
     *
     * SECURITY NOTE: When totalDeposits == 0, utilization is defined as 0
     * to prevent division-by-zero and ensure the pool returns the base rate.
     */
    function getBorrowRate(uint256 totalDeposits, uint256 totalBorrows) external pure override returns (uint256) {
        uint256 util = _utilizationRate(totalDeposits, totalBorrows);

        if (util <= KINK) {
            // Below kink: baseRate + utilization * slope1
            return BASE_RATE + util.wadMul(SLOPE_1);
        } else {
            // Above kink: baseRate + kink * slope1 + (util - kink) * slope2
            uint256 normalRate = KINK.wadMul(SLOPE_1);
            uint256 excessUtil = util - KINK;
            uint256 excessRate = excessUtil.wadMul(SLOPE_2);
            return BASE_RATE + normalRate + excessRate;
        }
    }

    /**
     * @inheritdoc IInterestRateModel
     * @dev Supply rate = borrowRate * utilization * (1 - reserveFactor)
     *
     * SECURITY NOTE: Interest earned by depositors is reduced by the
     * reserve factor, which accrues to the protocol treasury.
     */
    function getSupplyRate(uint256 totalDeposits, uint256 totalBorrows) external pure override returns (uint256) {
        uint256 util = _utilizationRate(totalDeposits, totalBorrows);
        uint256 borrowRate = _getBorrowRate(util);

        // supplyRate = borrowRate * utilization * (1 - reserveFactor)
        uint256 oneMinusReserve = WadRayMath.WAD - RESERVE_FACTOR;
        return borrowRate.wadMul(util).wadMul(oneMinusReserve);
    }

    /**
     * @inheritdoc IInterestRateModel
     */
    function utilizationRate(uint256 totalDeposits, uint256 totalBorrows) external pure override returns (uint256) {
        return _utilizationRate(totalDeposits, totalBorrows);
    }

