pragma solidity ^0.8.20;

/**
 * @title ILendingPool
 * @notice Interface for the core DeFi lending pool contract.
 * @dev Defines the external functions for depositing, withdrawing,
 *      borrowing, repaying, and liquidating positions.
 */
interface ILendingPool {
    // ══════════════════════════════════════════════════════════════════
    //                           EVENTS
    // ══════════════════════════════════════════════════════════════════

    event Deposit(address indexed user, uint256 amount, uint256 timestamp);
    event Withdraw(address indexed user, uint256 amount, uint256 timestamp);
    event Borrow(address indexed user, uint256 amount, uint256 timestamp);
    event Repay(address indexed user, uint256 amount, uint256 timestamp);
    event Liquidation(
        address indexed liquidator,
        address indexed borrower,
        uint256 debtRepaid,
        uint256 collateralSeized,
        uint256 timestamp
    );

    // ══════════════════════════════════════════════════════════════════
    //                        CORE FUNCTIONS
    // ══════════════════════════════════════════════════════════════════

    /**
     * @notice Deposit ETH as collateral into the lending pool.
     */
    function deposit() external payable;

    /**
     * @notice Withdraw deposited collateral.
     * @param amount The amount of ETH to withdraw.
     */
    function withdraw(uint256 amount) external;

    /**
     * @notice Borrow ETH against deposited collateral.
     * @param amount The amount of ETH to borrow.
     */
    function borrow(uint256 amount) external;

    /**
     * @notice Repay an outstanding loan.
     */
    function repay() external payable;

    /**
     * @notice Liquidate an undercollateralized borrower's position.
     * @param borrower The address of the borrower to liquidate.
     */
    function liquidate(address borrower) external payable;

    // ══════════════════════════════════════════════════════════════════
    //                        VIEW FUNCTIONS
    // ══════════════════════════════════════════════════════════════════

    /**
     * @notice Get the health factor of a user's position.
     * @param user The address of the user.
     * @return The health factor (scaled by 1e18). < 1e18 means liquidatable.
     */
    function healthFactor(address user) external view returns (uint256);

    /**
     * @notice Get total deposits in the pool.
     * @return The total deposited ETH amount.
     */
    function totalDeposits() external view returns (uint256);

    /**
     * @notice Get total borrows from the pool.
     * @return The total borrowed ETH amount.
     */
    function totalBorrows() external view returns (uint256);

    /**
     * @notice Get the deposit balance of a specific user.
     * @param user The address to query.
     * @return The user's deposited amount.
     */
    function getUserDeposit(address user) external view returns (uint256);

    /**
     * @notice Get the borrow balance of a specific user.
     * @param user The address to query.
     * @return The user's borrowed amount including accrued interest.
     */
    function getUserBorrow(address user) external view returns (uint256);
}

